import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"2017Q4 Ceph社区季度进展报告","description":"","frontmatter":{"title":"2017Q4 Ceph社区季度进展报告","date":"2017-12-01T00:00:00.000Z","updated":"2017-12-01T00:00:00.000Z","tags":["Ceph","社区动态","季度报告"],"categories":["季度总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2017Q4_Ceph社区季度总结.md","filePath":"posts/2017/2017Q4_Ceph社区季度总结.md","lastUpdated":1780460162000}'),l={name:"posts/2017/2017Q4_Ceph社区季度总结.md"};function h(i,e,n,_,p,s){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="ceph-社区-2017q4-季度进展报告" tabindex="-1">Ceph 社区 2017Q4 季度进展报告 <a class="header-anchor" href="#ceph-社区-2017q4-季度进展报告" aria-label="Permalink to &quot;Ceph 社区 2017Q4 季度进展报告&quot;">​</a></h1><h2 id="_1-本季度重点议题" tabindex="-1">1. 本季度重点议题 <a class="header-anchor" href="#_1-本季度重点议题" aria-label="Permalink to &quot;1. 本季度重点议题&quot;">​</a></h2><p>本季度 Ceph 社区围绕以下几个核心方向展开了深入讨论：</p><p><strong>OSD 架构重构</strong>是本季度最突出的主题。两次开发者月度会议均涉及 OSD 层面的改进，包括模块化设计、异步事件驱动模型，以及 PG 日志的存储优化。详见 <a href="./2017-DEC-06_-_Ceph_Developer_Monthly.html">2017-DEC-06_-_-_Ceph_Developer_Monthly</a> 和 <a href="/VideoSummary/posts/2017/2017-NOV-01_-_-_Ceph_Developer_Monthly.html">2017-NOV-01_-_-_Ceph_Developer_Monthly</a>)。</p><p><strong>异步编程框架引入</strong>同样贯穿本季度，包括 C++17 async 库的评估、C++ 协程的探索，以及 DPDK/SPDK 在网络和存储 IO 层的应用可能性。</p><p><strong>存储介质演进适配</strong>：随着 NVMe 和全闪存部署的普及，社区开始系统性地讨论如何针对新介质特性优化 Ceph 的数据路径和日志机制。</p><hr><h2 id="_2-技术亮点" tabindex="-1">2. 技术亮点 <a class="header-anchor" href="#_2-技术亮点" aria-label="Permalink to &quot;2. 技术亮点&quot;">​</a></h2><h3 id="pg-日志优化-2017-nov-01-ceph-developer-monthly" tabindex="-1">PG 日志优化（<a href="/VideoSummary/posts/2017/2017-NOV-01_-_-_Ceph_Developer_Monthly.html">2017-NOV-01_-_-_Ceph_Developer_Monthly</a>)） <a class="header-anchor" href="#pg-日志优化-2017-nov-01-ceph-developer-monthly" aria-label="Permalink to &quot;PG 日志优化（[2017-NOV-01_-_-_Ceph_Developer_Monthly](/posts/2017/2017-NOV-01_-_-_Ceph_Developer_Monthly))）&quot;">​</a></h3><p>针对 SD 场景下 PG 日志带来的写放大、CPU 和内存开销问题，社区提出了两项具体改进：</p><ul><li>在 SSD 上使用**环形缓冲区（Ring Buffer）**存储 PG 日志，降低写放大</li><li>引入 <strong>FIFO 压缩模式</strong>，简化数据结构、提升处理效率</li><li>将 PG 日志与其他内部元数据分离存储，减少内存占用</li></ul><h3 id="快照修剪-snapshot-triming-改进" tabindex="-1">快照修剪（Snapshot Triming）改进 <a class="header-anchor" href="#快照修剪-snapshot-triming-改进" aria-label="Permalink to &quot;快照修剪（Snapshot Triming）改进&quot;">​</a></h3><ul><li>采用<strong>增量数据结构</strong>替代现有方案，降低 CPU 开销</li><li>将快照修剪逻辑与缓存淘汰（Cache Eviction）解耦，独立处理</li></ul><h3 id="osd-模块化与性能重构-2017-dec-06-ceph-developer-monthly" tabindex="-1">OSD 模块化与性能重构（<a href="/VideoSummary/posts/2017/2017-DEC-06_-_-_Ceph_Developer_Monthly.html">2017-DEC-06_-_-_Ceph_Developer_Monthly</a>)） <a class="header-anchor" href="#osd-模块化与性能重构-2017-dec-06-ceph-developer-monthly" aria-label="Permalink to &quot;OSD 模块化与性能重构（[2017-DEC-06_-_-_Ceph_Developer_Monthly](/posts/2017/2017-DEC-06_-_-_Ceph_Developer_Monthly))）&quot;">​</a></h3><ul><li>探索基于 <strong>DPDK</strong>（网络）和 <strong>SPDK</strong>（存储 IO）的高性能数据路径</li><li>减少数据结构中的不必要拷贝和内存分配，提升 CPU 利用率</li><li>讨论多种新型存储池模型： <ul><li>非复制池，直接写入 SPDK</li><li>并行多副本写入池，支持不同一致性和容错模型</li><li>面向 Fabrics 的池，直接在 Fabrics 层写入所有副本</li></ul></li></ul><h3 id="ceph-manager-组件成熟" tabindex="-1">Ceph Manager 组件成熟 <a class="header-anchor" href="#ceph-manager-组件成熟" aria-label="Permalink to &quot;Ceph Manager 组件成熟&quot;">​</a></h3><p><a href="/VideoSummary/posts/2017/Ceph_Promo_Video_2017.html">Ceph_Promo_Video_2017</a>) 中明确介绍了 <strong>Ceph Manager</strong> 作为新组件的定位：承接分析 API 和管理功能，使 Monitor 专注于关键集群状态，从而支撑更大规模的集群部署。</p><h3 id="rgw-云同步功能" tabindex="-1">RGW 云同步功能 <a class="header-anchor" href="#rgw-云同步功能" aria-label="Permalink to &quot;RGW 云同步功能&quot;">​</a></h3><p>本季度提及了 RGW（Rados Gateway）的**云同步（Cloud Sync）**功能进展，支持跨数据中心、跨地理位置的集群联合，以及基于 ACL 的认证机制。</p><hr><h2 id="_3-重要决策与里程碑" tabindex="-1">3. 重要决策与里程碑 <a class="header-anchor" href="#_3-重要决策与里程碑" aria-label="Permalink to &quot;3. 重要决策与里程碑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>决策</th><th>说明</th></tr></thead><tbody><tr><td>PG 日志环形缓冲区</td><td>确定在 SSD 场景下采用环形缓冲区 + FIFO 压缩模式</td></tr><tr><td>快照修剪算法重写</td><td>决定引入增量数据结构并优化修剪算法</td></tr><tr><td>C++17 async 重构启动</td><td>决定开始将部分阻塞代码迁移至异步模式</td></tr><tr><td>PT 合并方案讨论</td><td>确定需保证合并过程可逆，并对齐 PT 日志后再合并</td></tr></tbody></table><p><strong>Ceph Dashboard</strong> 开发项目在本季度由 Red Hat 推进，作为管理界面的重要组成部分被提及。</p><hr><h2 id="_4-社区动态" tabindex="-1">4. 社区动态 <a class="header-anchor" href="#_4-社区动态" aria-label="Permalink to &quot;4. 社区动态&quot;">​</a></h2><ul><li><strong>开发者月度会议（CDM）</strong>：本季度至少举行了两次，分别在 11 月和 12 月，参与者包括 Greg、Josh、Sage、Mark、Adam、Casey 等核心贡献者，讨论议题覆盖 OSD 重构、PG 日志、快照修剪和异步框架。</li><li><strong>Ceph 宣传视频发布</strong>：<a href="/VideoSummary/posts/2017/Ceph_Promo_Video_2017.html">Ceph_Promo_Video_2017</a>) 系统性地介绍了 Ceph 的架构（RADOS、OSD、Monitor、Ceph Manager）及三大接口（RGW、RBD、CephFS），面向更广泛受众推广 Ceph 生态。</li><li><strong>Red Hat 持续投入</strong>：Red Hat 在本季度主导了 Ceph Dashboard 的开发，体现了商业力量对社区的持续贡献。</li></ul><hr><h2 id="_5-下季度展望" tabindex="-1">5. 下季度展望 <a class="header-anchor" href="#_5-下季度展望" aria-label="Permalink to &quot;5. 下季度展望&quot;">​</a></h2><p>基于本季度的讨论方向，预计 2018Q1 将重点推进以下工作：</p><ol><li><strong>DPDK/SPDK 集成原型</strong>：本季度已完成方向确认，下季度有望出现早期原型或 RFC</li><li><strong>C++17 async 重构落地</strong>：代码重构已启动，预计将有更多模块完成异步化改造</li><li><strong>PG 日志环形缓冲区实现</strong>：决策已定，实现和评估工作将在下季度展开</li><li><strong>Ceph Dashboard 功能完善</strong>：Red Hat 主导的仪表板项目将持续迭代</li><li><strong>新型存储池模型 RFC</strong>：多种池模型的讨论已较为成熟，预计进入正式提案阶段</li><li><strong>RGW 云同步功能推进</strong>：跨数据中心同步能力将进一步完善</li></ol><hr><blockquote><p>本报告基于 2017Q4 季度三篇会议/视频总结材料生成，部分议题（如具体版本发布信息）在本季度材料中未出现，故未作记录。</p></blockquote><hr><h2 id="参考文章" tabindex="-1">参考文章 <a class="header-anchor" href="#参考文章" aria-label="Permalink to &quot;参考文章&quot;">​</a></h2><ul><li><a href="/VideoSummary/posts/2017/2017-DEC-06_-_-_Ceph_Developer_Monthly.html">2017-DEC-06 :: Ceph Developer Monthly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-NOV-01_-_-_Ceph_Developer_Monthly.html">2017-NOV-01 :: Ceph Developer Monthly</a>)</li><li><a href="/VideoSummary/posts/2017/Ceph_Promo_Video_2017.html">Ceph Promo Video 2017</a>)</li></ul>',35)])])}const m=a(l,[["render",h]]);export{C as __pageData,m as default};
